-- Pale Reach additions from the 2026-10-11 CoA world database export (pale_reach_and_redridge.sql).
-- Also sets Smart Steam Tank templates 165513/165514 and adds ordinary loot and gold
-- (lootid/mingold/maxgold) to 98 Pale Reach creatures; untested.

INSERT INTO `creature_template` (
    `entry`, `name`,
    `faction`, `minlevel`,
    `maxlevel`, `npcflag`,
    `speed_walk`, `speed_run`,
    `unit_flags`, `VehicleId`,
    `AIName`
) VALUES
(
    165513, 'Smart Tank', 35, 30, 30, 16777216, 1.2, 1.4, 16384, 117, 'SmartAI'
),
(
    165514, 'Smart Tank', 35, 30, 30, 16777216, 1.2, 1.4, 16384, 117, 'SmartAI'
)
ON DUPLICATE KEY UPDATE
    `minlevel` = VALUES(`minlevel`),
    `maxlevel` = VALUES(`maxlevel`),
    `speed_walk` = VALUES(`speed_walk`),
    `speed_run` = VALUES(`speed_run`),
    `VehicleId` = VALUES(`VehicleId`),
    `AIName` = VALUES(`AIName`),
    `npcflag` = `npcflag` | VALUES(`npcflag`),
    `unit_flags` = `unit_flags` | VALUES(`unit_flags`);

